style.css:
/* Change cursor to a fighter jet icon */
* {
  cursor: url('https://upload.wikimedia.org/wikipedia/commons/e/eb/F-16_Fighting_Falcon.svg') 16 16, auto !important;
}

/* Add fighter jet background watermark to websites */
body::before {
  content: "";
  background: url('https://upload.wikimedia.org/wikipedia/commons/2/2f/F-35A_fighter_jet.svg') no-repeat center center;
  background-size: 200px;
  opacity: 0.05;
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: -1;
}

/* Add a small fighter jet icon next to all links */
a::after {
  content: " ✈️";
  font-size: 0.8em;
  margin-left: 4px;
  color: #007BFF;
}

/* Add subtle fighter jet-themed borders to buttons */
button, input[type="submit"], input[type="button"] {
  border: 2px solid #007BFF;
  border-radius: 5px;
  background: linear-gradient(135deg, #007BFF, #0056b3);
  color: white;
}

button:hover, input[type="submit"]:hover, input[type="button"]:hover {
  background: linear-gradient(135deg, #0056b3, #003f7f);
}
